'use client';
import Link from"next/link";import{useEffect,useState}from"react";import Nav from"../../components/Nav";import StatusBadge from"../../components/StatusBadge";import{readContract,formatGen,toBigIntString}from"../../lib/contract";
export default function Disputes(){const[items,setItems]=useState([]);const[msg,setMsg]=useState("Loading agreements…");async function load(){try{const n=Number(toBigIntString(await readContract("get_dispute_count")));const r=[];for(let i=0;i<n;i++){try{r.push(await readContract("get_dispute",[i]))}catch{}}setItems(r.reverse());setMsg(r.length?"":"No agreements found yet.")}catch(e){setMsg(e?.message||"Could not load agreements.")}}useEffect(()=>{load()},[]);
return <><Nav/><main className="shell"><div className="flex justify-between items-end"><div><span className="badge text-cyan-300">AGREEMENTS</span><h1 className="mt-4 text-4xl font-black">Dispute explorer</h1></div><button className="btn btn-dark" onClick={load}>Refresh</button></div>{msg&&<p className="mt-8 muted">{msg}</p>}<div className="mt-8 grid-auto">{items.map(d=><Link href={`/disputes/${String(d.id)}`} className="card p-6" key={String(d.id)}><div className="flex justify-between"><span className="text-sm text-slate-500">#{String(d.id)}</span><StatusBadge status={d.status}/></div><h2 className="mt-5 text-xl font-bold">{d.title}</h2><p className="mt-2 text-sm muted">{d.requirements}</p><div className="mt-6 flex justify-between text-sm"><span className="muted">Escrow</span><span>{formatGen(d.amount)}</span></div><div className="mt-2 flex justify-between text-sm"><span className="muted">Score</span><span>{String(d.score)} / 100</span></div></Link>)}</div></main></>}